      const below = totals[grade] ?? null;
      const own = asOf
        ? []
        : this.ownPeople()
            .filter((p) => !p.retired && p.grade === grade)
            .map((p) => p.dueTotal);
      return { grade, dueTotal: sumSkippingNa([...own, below]) };
    });
  });
